/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'

const mode = process.argv[2]

// Validate mode argument
if (mode !== 'rounds' && mode !== 'tally') {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

// Read stdin
const input = readFileSync(0, 'utf8')

try {
  const { candidates, ballots } = parseInput(input)

  if (candidates.length === 0) {
    process.stderr.write('error: no candidates\n')
    process.exit(2)
  }

  const result = runElection(candidates, ballots)

  if (mode === 'rounds') {
    for (const round of result.rounds) {
      printRound(round, candidates)
    }
  } else {
    process.stdout.write(`rounds ${result.rounds.length}\n`)
  }

  if (result.winner) {
    process.stdout.write(`winner ${result.winner}\n`)
  } else {
    process.stdout.write('no winner\n')
  }

  process.exit(0)
} catch (error) {
  process.stderr.write(error.message + '\n')
  process.exit(2)
}

function parseInput(input) {
  const lines = input.split('\n')

  // Drop empty tail from trailing newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const candidates = []
  const ballots = []
  let candidatesDeclared = false

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    let line = lines[lineNum].trim()

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) {
      continue
    }

    // Split on runs of whitespace
    const parts = line.split(/\s+/)
    const directive = parts[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw new Error(`error: line ${lineNum + 1}: candidates must be declared once, before any ballot`)
      }
      if (parts.length < 2) {
        throw new Error(`error: line ${lineNum + 1}: expected candidates <name>...`)
      }

      const names = parts.slice(1)
      const seen = new Set()

      for (const name of names) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) {
          throw new Error(`error: line ${lineNum + 1}: invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          throw new Error(`error: line ${lineNum + 1}: candidate ${name} is declared twice`)
        }
        seen.add(name)
        candidates.push(name)
      }

      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw new Error(`error: line ${lineNum + 1}: candidates must be declared once, before any ballot`)
      }
      if (parts.length < 3) {
        throw new Error(`error: line ${lineNum + 1}: expected ballot <count> <candidate>...`)
      }

      // Parse count
      const countStr = parts[1]
      if (!/^\d+$/.test(countStr) || countStr === '0' || (countStr.length > 1 && countStr[0] === '0')) {
        throw new Error(`error: line ${lineNum + 1}: count must be a positive integer`)
      }
      const count = parseInt(countStr, 10)

      // Parse ballot choices
      const choices = parts.slice(2)
      const candidateSet = new Set(candidates)
      const seenInBallot = new Set()

      for (const choice of choices) {
        if (!candidateSet.has(choice)) {
          throw new Error(`error: line ${lineNum + 1}: unknown candidate ${choice}`)
        }
        if (seenInBallot.has(choice)) {
          throw new Error(`error: line ${lineNum + 1}: candidate ${choice} is repeated`)
        }
        seenInBallot.add(choice)
      }

      ballots.push({ count, choices })
    } else {
      throw new Error(`error: line ${lineNum + 1}: unknown directive ${directive}`)
    }
  }

  return { candidates, ballots }
}

function runElection(candidates, ballots) {
  const rounds = []
  const continuing = new Set(candidates)
  const voteHistory = {} // candidate -> array of vote counts per round

  // Initialize vote history
  for (const candidate of candidates) {
    voteHistory[candidate] = []
  }

  let roundNum = 0
  while (true) {
    roundNum++

    // Count votes in this round
    const votes = {}
    let exhausted = 0

    for (const candidate of candidates) {
      votes[candidate] = 0
    }

    for (const { count, choices } of ballots) {
      let voted = false
      for (const choice of choices) {
        if (continuing.has(choice)) {
          votes[choice] += count
          voted = true
          break
        }
      }
      if (!voted) {
        exhausted += count
      }
    }

    // Record votes for this round
    for (const candidate of candidates) {
      voteHistory[candidate].push(votes[candidate])
    }

    // Store round info
    const roundInfo = {
      votes: { ...votes },
      exhausted,
      continuing: new Set(continuing),
      roundNum
    }
    rounds.push(roundInfo)

    // Calculate active total
    const activeTotal = Object.values(votes)
      .filter((_, i) => continuing.has(candidates[i]))
      .reduce((a, b) => a + b, 0)

    // Check for majority
    let winner = null
    for (const candidate of continuing) {
      if (votes[candidate] * 2 > activeTotal) {
        winner = candidate
        break
      }
    }

    if (winner || activeTotal === 0) {
      return {
        rounds,
        winner: winner || null
      }
    }

    // Eliminate candidate with fewest votes
    const candidateToEliminate = findCandidateToEliminate(continuing, voteHistory, roundNum)
    continuing.delete(candidateToEliminate)
    roundInfo.eliminated = candidateToEliminate
  }
}

function findCandidateToEliminate(continuing, voteHistory, roundNum) {
  // Get vote counts for this round for continuing candidates
  const candidates = Array.from(continuing)

  // Find the candidate(s) with fewest votes in this round
  let fewest = candidates[0]
  let fewestCount = voteHistory[fewest][roundNum - 1]

  for (const candidate of candidates) {
    const count = voteHistory[candidate][roundNum - 1]
    if (count < fewestCount) {
      fewest = candidate
      fewestCount = count
    }
  }

  // Get all candidates tied with fewest votes
  const tied = candidates.filter(c => voteHistory[c][roundNum - 1] === fewestCount)

  if (tied.length === 1) {
    return tied[0]
  }

  // Tiebreaker: compare across rounds from first to current
  for (let round = 0; round < roundNum; round++) {
    const roundVotes = {}
    for (const candidate of tied) {
      roundVotes[candidate] = voteHistory[candidate][round]
    }

    // Find minimum in this round
    let minVotes = Math.min(...tied.map(c => voteHistory[c][round]))

    // Keep only those with minimum votes in this round
    const survivors = tied.filter(c => voteHistory[c][round] === minVotes)

    if (survivors.length === 1) {
      return survivors[0]
    }

    // Continue with survivors for next round
    tied.splice(0, tied.length, ...survivors)
  }

  // If no round separates them, eliminate by descending name (alphabetically last)
  tied.sort()
  return tied[tied.length - 1]
}

function printRound(roundInfo, allCandidates) {
  const { votes, exhausted, continuing, eliminated, roundNum } = roundInfo

  // Get continuing candidates sorted by vote count (descending), then name (ascending)
  const sorted = Array.from(continuing).sort((a, b) => {
    const countDiff = votes[b] - votes[a]
    if (countDiff !== 0) return countDiff
    return a.localeCompare(b)
  })

  let line = `round ${roundNum}: `
  line += sorted.map(c => `${c}=${votes[c]}`).join(' ')
  line += ` exhausted=${exhausted}`

  process.stdout.write(line + '\n')

  if (eliminated) {
    process.stdout.write(`eliminated ${eliminated}\n`)
  }
}
"}

