{"file_path":"src/count.js","content":"/** The instant-runoff count itself: rounds, eliminations and the winner. */

import { compareNames } from './report.js'

/**
 * Counts the election in rounds, returning every round counted and the winner,
 * or null when no candidate ever reached the majority.
 */
export function runElection(candidates, ballots) {
  const rounds = []
  const continuing = new Set(candidates)
  const history = new Map() // candidate -> its votes in each round, oldest first
  for (const candidate of candidates) history.set(candidate, [])

  let roundNum = 0
  while (true) {
    roundNum++

    const votes = new Map()
    for (const candidate of candidates) votes.set(candidate, 0)
    let exhausted = 0

    for (const { count, choices } of ballots) {
      let counted = false
      for (const choice of choices) {
        if (continuing.has(choice)) {
          votes.set(choice, votes.get(choice) + count)
          counted = true
          break
        }
      }
      if (!counted) exhausted += count
    }

    for (const candidate of candidates) history.get(candidate).push(votes.get(candidate))

    const standing = [...continuing]
    const round = { roundNum, votes, exhausted, standing, eliminated: null }
    rounds.push(round)

    let activeTotal = 0
    for (const candidate of standing) activeTotal += votes.get(candidate)

    if (activeTotal === 0) return { rounds, winner: null }

    let winner = null
    for (const candidate of standing) {
      if (votes.get(candidate) * 2 > activeTotal) {
        winner = candidate
        break
      }
    }
    if (winner !== null) return { rounds, winner }

    const doomed = chooseElimination(standing, history, roundNum)
    continuing.delete(doomed)
    round.eliminated = doomed
  }
}

/**
 * Picks the candidate to eliminate: fewest votes in the round just counted,
 * ties broken by replaying the rounds from the first onwards, and at the last
 * by the name that sorts latest.
 */
function chooseElimination(standing, history, roundNum) {
  let tied = fewestIn(standing, history, roundNum - 1)
  if (tied.length === 1) return tied[0]

  for (let round = 0; round < roundNum; round++) {
    tied = fewestIn(tied, history, round)
    if (tied.length === 1) return tied[0]
  }

  let last = tied[0]
  for (const candidate of tied) if (compareNames(candidate, last) > 0) last = candidate
  return last
}

/** Keeps the names holding the fewest votes in the given round. */
function fewestIn(names, history, round) {
  const counts = names.map(name => history.get(name)[round])
  const fewest = Math.min(...counts)
  return names.filter((name, i) => counts[i] === fewest)
}
"}

