{"file_path":"src/report.js","content":"/** Rendering the rounds of a count. */

/** Orders names by Unicode code point, ascending. */
export function compareNames(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

/** Renders one round, followed by its elimination line when there was one. */
export function formatRound(round) {
  const { votes, exhausted, standing, eliminated, roundNum } = round

  const ordered = standing.slice().sort((a, b) => {
    const byVotes = votes.get(b) - votes.get(a)
    return byVotes !== 0 ? byVotes : compareNames(a, b)
  })

  const parts = ordered.map(name => `${name}=${votes.get(name)}`)
  parts.push(`exhausted=${exhausted}`)

  let text = `round ${roundNum}: ${parts.join(' ')}\n`
  if (eliminated !== null) text += `eliminated ${eliminated}\n`
  return text
}
"}

